using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Net;
using System.Net.Sockets;
using System.Threading;
using System.Threading.Tasks;
namespace ZapretManager {
public static class ExclusionTests {
 public static void SendTcpProbe(){using(var s=new TcpClient()){try{s.BeginConnect("192.0.2.123",43998,null,null);Thread.Sleep(1200);}catch(SocketException){}}}
 public static void SendProbe(){using(var s=new UdpClient(new IPEndPoint(IPAddress.Any,0))){for(int n=0;n<8;n++){byte[] b=System.Text.Encoding.ASCII.GetBytes("zapret2-exclusion-test");s.Send(b,b.Length,"192.0.2.123",43999);Thread.Sleep(100);}}}
 public static async Task<int> Run(string report){var lines=new List<string>();int failures=0;Action<bool,string> check=(ok,name)=>{lines.Add((ok?"PASS: ":"FAIL: ")+name);if(!ok)failures++;File.WriteAllLines(report,lines);};string config=Core.PathOf("app-exclusions.json");byte[] old=File.Exists(config)?File.ReadAllBytes(config):null;Process worker=null;IntPtr observer=IntPtr.Zero;CancellationTokenSource quit=null;Task receive=null;string selected=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"selected-probe.exe"),other=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"other-probe.exe");try{
  string exe=System.Reflection.Assembly.GetExecutingAssembly().Location;var c=new ExclusionConfig {Applications=new[]{exe}};
  check(Exclusions.Matches(c,exe.ToUpperInvariant()),"EXE path matching ignores case");check(!Exclusions.Matches(c,Path.Combine(Path.GetTempPath(),Path.GetFileName(exe))),"same filename in another directory is not excluded");c.Enabled=false;check(!Exclusions.Matches(c,exe),"disabled exclusions do not bypass any EXE");bool bad=false;try{Exclusions.Normalize("steam.exe");}catch(ArgumentException){bad=true;}check(bad,"relative EXE paths rejected");check(ExclusionWorker.ProcessPath(Process.GetCurrentProcess().Id)==exe,"Windows process owner resolves full executable path");
  using(var udp=new UdpClient(new IPEndPoint(IPAddress.Any,0))){int p=((IPEndPoint)udp.Client.LocalEndPoint).Port;check(ExclusionWorker.Owner(false,2,"192.0.2.55",p,"192.0.2.123",43999)==Process.GetCurrentProcess().Id,"IPv4 UDP wildcard binding resolves owner PID");var benchmark=Stopwatch.StartNew();for(int n=0;n<1000;n++)ExclusionWorker.Owner(false,2,"192.0.2.55",p,"192.0.2.123",43999);lines.Add("MEASURE: 1000 UDP owner lookups = "+benchmark.ElapsedMilliseconds+" ms");}
  using(var udp=new UdpClient(AddressFamily.InterNetworkV6)){udp.Client.Bind(new IPEndPoint(IPAddress.IPv6Any,0));int p=((IPEndPoint)udp.Client.LocalEndPoint).Port;check(ExclusionWorker.Owner(false,23,"2001:db8::1",p,"2001:db8::2",43999)==Process.GetCurrentProcess().Id,"IPv6 UDP binding resolves owner PID");}
  var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();try{using(var client=new TcpClient()){await client.ConnectAsync(IPAddress.Loopback,((IPEndPoint)listener.LocalEndpoint).Port);using(var peer=await listener.AcceptTcpClientAsync()){var l=(IPEndPoint)client.Client.LocalEndPoint;var r=(IPEndPoint)client.Client.RemoteEndPoint;check(ExclusionWorker.Owner(true,2,l.Address.ToString(),l.Port,r.Address.ToString(),r.Port)==Process.GetCurrentProcess().Id,"TCP exact connection tuple resolves owner PID");check(ExclusionWorker.Owner(true,2,l.Address.ToString(),l.Port,r.Address.ToString(),r.Port+1)==0,"TCP remote-port mismatch cannot bypass another flow");}}}finally{listener.Stop();}
  File.Copy(exe,selected,true);File.Copy(exe,other,true);Core.Write(config,new ExclusionConfig {Applications=new[]{selected}});if(File.Exists(Core.PathOf("app-exclusions-status.json")))File.Delete(Core.PathOf("app-exclusions-status.json"));worker=Process.Start(new ProcessStartInfo(exe,"--exclusion-worker 20000"){UseShellExecute=false,CreateNoWindow=true});bool ready=false;for(int n=0;n<100;n++){await Task.Delay(100);if(worker.HasExited)break;if(File.Exists(Core.PathOf("app-exclusions-status.json"))&&Core.Read<ExclusionHealth>(Core.PathOf("app-exclusions-status.json")).Ready){ready=true;break;}}check(ready,"packet exclusion worker starts with official WinDivert driver");if(!ready)throw new Exception("Worker startup failed");
  ExclusionWorker.Initialize();observer=ExclusionWorker.WinDivertOpen("outbound and ip.DstAddr == 192.0.2.123 and ((udp and udp.DstPort == 43999) or (tcp and tcp.DstPort == 43998))",0,0,5);if(observer==new IntPtr(-1))throw new System.ComponentModel.Win32Exception(System.Runtime.InteropServices.Marshal.GetLastWin32Error());int seen=0;IntPtr observed=observer;receive=Task.Run(()=>{byte[] packet=new byte[65575],addr=new byte[80];uint size;while(ExclusionWorker.WinDivertRecv(observed,packet,(uint)packet.Length,out size,addr))Interlocked.Increment(ref seen);});
  var result=await Core.Run(selected,"--exclusion-probe",CancellationToken.None);await Task.Delay(300);check(result.Exit==0&&seen==0,"selected EXE's real UDP packets skip zapret priority entirely");
  result=await Core.Run(selected,"--exclusion-probe-tcp",CancellationToken.None);await Task.Delay(300);check(result.Exit==0&&seen==0,"selected EXE's real TCP SYN packets skip zapret priority entirely");
  result=await Core.Run(other,"--exclusion-probe",CancellationToken.None);await Task.Delay(300);check(result.Exit==0&&seen>=8,"different EXE to same destination still reaches zapret priority");var h=Core.Read<ExclusionHealth>(Core.PathOf("app-exclusions-status.json"));check(h.Bypassed>=8,"worker reports actual bypassed packets");
  Core.Write(config,new ExclusionConfig {Enabled=false,Applications=new[]{selected}});await Task.Delay(500);int before=seen;await Core.Run(selected,"--exclusion-probe",CancellationToken.None);await Task.Delay(300);check(seen-before>=8,"disabling exclusions immediately returns selected EXE to zapret");
  worker.Kill();worker.WaitForExit(3000);worker.Dispose();worker=null;Core.Write(config,new ExclusionConfig {Applications=new[]{selected}});
  string testService="zapret2-exclusions-test";bool created=false;try{Core.CreateAuxService(testService,Core.Quote(exe)+" --exclusion-service "+testService);created=true;using(var service=new System.ServiceProcess.ServiceController(testService)){service.Start();service.WaitForStatus(System.ServiceProcess.ServiceControllerStatus.Running,TimeSpan.FromSeconds(15));check(Core.Read<ExclusionHealth>(Core.PathOf("app-exclusions-status.json")).Ready,"Windows exclusion service is ready before startup completes");before=seen;await Core.Run(selected,"--exclusion-probe",CancellationToken.None);await Task.Delay(300);check(seen==before,"background Windows service applies process exclusion without UI");service.Stop();service.WaitForStatus(System.ServiceProcess.ServiceControllerStatus.Stopped,TimeSpan.FromSeconds(15));service.Start();service.WaitForStatus(System.ServiceProcess.ServiceControllerStatus.Running,TimeSpan.FromSeconds(15));check(true,"Windows exclusion service stops and restarts");service.Stop();service.WaitForStatus(System.ServiceProcess.ServiceControllerStatus.Stopped,TimeSpan.FromSeconds(15));}}finally{if(created){using(var service=new System.ServiceProcess.ServiceController(testService)){try{if(service.Status!=System.ServiceProcess.ServiceControllerStatus.Stopped){service.Stop();service.WaitForStatus(System.ServiceProcess.ServiceControllerStatus.Stopped,TimeSpan.FromSeconds(15));}}catch{}}Core.Run(Path.Combine(Environment.SystemDirectory,"sc.exe"),"delete "+testService,CancellationToken.None).GetAwaiter().GetResult();}}
 }catch(Exception e){check(false,e.ToString());}finally{if(observer!=IntPtr.Zero&&observer!=new IntPtr(-1)){ExclusionWorker.WinDivertShutdown(observer,1);if(receive!=null)try{receive.GetAwaiter().GetResult();}catch{}ExclusionWorker.WinDivertClose(observer);}if(worker!=null){if(!worker.HasExited){Core.Write(config,new ExclusionConfig {Enabled=false});Thread.Sleep(300);worker.Kill();worker.WaitForExit(3000);}worker.Dispose();}if(old==null)File.Delete(config);else File.WriteAllBytes(config,old);foreach(string f in new[]{selected,other})if(File.Exists(f))File.Delete(f);if(quit!=null)quit.Dispose();}lines.Add("Failures: "+failures);File.WriteAllLines(report,lines);return failures==0?0:1;
 }
}
}
